DG.put("ath-pakhyaan-charitr-likhyate/97",{"n":97,"title":null,"title_roman":null,"page":1379,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1379,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":1379,"lines":[{"gurmukhi":"ਸਯਾਲਕੋਟ ਕੇ ਦੇਸ ਮੈ ਸਾਲਬਾਹਨ ਰਾਵ।","roman":"Sayaalkot ke des mai saalbaahan raav |","meaning_en":"In the land of Sialkot there was a king, Salbahan;","page":1379,"meaning_status":"draft"},{"gurmukhi":"ਖਟ ਦਰਸਨ ਕੌ ਮਾਨਈ ਰਾਖਤ ਸਭ ਕੋ ਭਾਵ। ੧।","roman":"Khat darsan kau maanaee raakhat sabh ko bhaav | 1 |","meaning_en":"he honoured the six schools of philosophy and kept regard for all.","page":1379,"meaning_status":"draft"}]},{"type":"verse","number":[2],"number_text":"੨।","page":1379,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਤ੍ਰਿਪਰਾਰਿ ਮਤੀ ਹੁਤੀ ਤਾ ਕੀ ਤ੍ਰਿਯ ਕੌ ਨਾਮ।","roman":"Sree tripraari matee hutee taa kee triy kau naam |","meaning_en":"Sri Triprari Mati was the name of his wife;","page":1379,"meaning_status":"draft"},{"gurmukhi":"ਭਜੈ ਭਵਾਨੀ ਕੌ ਸਦਾ ਨਿਸੁ ਦਿਨ ਆਠੌ ਜਾਮ। ੨।","roman":"Bhajai bhavaanee kau sadaa nisu din aathau jaam | 2 |","meaning_en":"she worshipped Bhavani always, night and day, through all eight watches.","page":1379,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1379,"meaning_status":"draft"},{"type":"verse","number":[3],"number_text":"੩।","page":1379,"lines":[{"gurmukhi":"ਯਹ ਜਬ ਭੇਦ ਬਿਕ੍ਰਮੈ ਪਾਯੋ। ਅਮਿਤ ਸੈਨ ਲੈ ਕੈ ਚੜਿ ਧਾਯੋ।","roman":"Yah jab bhed bikramai paayo | amit sain lai kai chari dhaayo |","meaning_en":"When Bikram learned this secret, he took a countless army and marched to attack.","page":1379,"meaning_status":"draft","note":"ਯਹ ਭੇਦ: 'this secret'; what it refers to is not stated in the text."},{"gurmukhi":"ਨੈਕੁ ਸਾਲਬਾਹਨ ਨਹਿ ਡਰਿਯੋ। ਜੋਰਿ ਸੂਰ ਸਨਮੁਖ ਹ੍ਵੈ ਲਰਿਯੋ। ੩।","roman":"Naiku saalbaahan nahi dariyo | jori soor sanmukh hvai lariyo | 3 |","meaning_en":"Salbahan was not in the least afraid; gathering his warriors he fought him face to face.","page":1379,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1379,"meaning_status":"draft"},{"type":"verse","number":[4],"number_text":"੪।","page":1379,"lines":[{"gurmukhi":"ਤਬ ਤਾ ਸੌ ਸ੍ਰੀ ਚੰਡਿਕਾ ਐਸੇ ਕਹਿਯੋ ਬਨਾਇ।","roman":"Tab taa sau sree chandikaa aise kahiyo banaai |","meaning_en":"Then Sri Chandika spoke to him thus:","page":1379,"meaning_status":"draft"},{"gurmukhi":"ਸੈਨ ਮ੍ਰਿਤਕਾ ਕੀ ਰਚੋ ਤੁਮ ਮੈ ਦੇਉ ਜਿਯਾਇ। ੪।","roman":"Sain mritkaa kee racho tum mai deu jiyaai | 4 |","meaning_en":"\"Fashion an army of clay; I shall bring it to life.\"","page":1379,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1379,"meaning_status":"draft"},{"type":"verse","number":[5],"number_text":"੫।","page":1379,"lines":[{"gurmukhi":"ਜੋ ਜਗਮਾਤ ਕਹਿਯੋ ਸੋ ਕੀਨੋ। ਸੈਨ ਮ੍ਰਿਤਕਾ ਕੀ ਰਚਿ ਲੀਨੋ।","roman":"Jo jagmaat kahiyo so keeno | sain mritkaa kee rachi leeno |","meaning_en":"He did what the Mother of the World said, and fashioned an army of clay.","page":1379,"meaning_status":"draft"},{"gurmukhi":"ਕ੍ਰਿਪਾ ਦ੍ਰਿਸਟਿ ਸ੍ਰੀ ਚੰਡਿ ਨਿਹਾਰੇ। ਜਗੇ ਸੂਰ ਹਥਿਆਰ ਸੰਭਾਰੇ। ੫।","roman":"Kripaa dristi sree chandi nihaare | jage soor hathiaar sanbhaare | 5 |","meaning_en":"Sri Chandi looked on it with a glance of grace; the warriors awoke and took up their weapons.","page":1379,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1379,"meaning_status":"draft"},{"type":"verse","number":[6],"number_text":"੬।","page":1379,"lines":[{"gurmukhi":"ਮਾਟੀ ਤੇ ਮਰਦ ਊਪਜੇ ਕਰਿ ਕੈ ਕ੍ਰੁਧ ਬਿਸੇਖ।","roman":"Maatee te marad oopje kari kai krudh bisekh |","meaning_en":"From the clay men arose, filled with great wrath;","page":1379,"meaning_status":"draft"},{"gurmukhi":"ਹੈ ਗੈ ਰਥ ਪੈਦਲ ਘਨੇ ਨ੍ਰਿਪ ਉਠਿ ਚਲੇ ਅਨੇਕ। ੬।","roman":"Hai gai rath paidal ghane nrip uthi chale anek | 6 |","meaning_en":"horses, elephants, chariots, many foot-soldiers and many kings rose up and marched.","page":1379,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1379,"meaning_status":"draft"},{"type":"verse","number":[7],"number_text":"੭।","page":1379,"lines":[{"gurmukhi":"ਗਹਿਰੇ ਨਾਦ ਨਗਰ ਮੈ ਬਾਜੇ। ਗਹਿ ਗਹਿ ਗੁਰਜ ਗਰਬਿਯਾ ਗਾਜੇ।","roman":"Gahire naad nagar mai baaje | gahi gahi guraj garbiyaa gaaje |","meaning_en":"Deep-toned drums sounded in the city; grasping their maces the proud ones roared.","page":1379,"meaning_status":"draft"},{"gurmukhi":"ਟੂਕ ਟੂਕ ਭਾਖੈ ਜੋ ਹ੍ਵੈ ਹੈ। ਬਹੁਰੋ ਫੇਰਿ ਧਾਮ ਨਹਿ ਜੈਹੈ। ੭।","roman":"Took took bhaakhai jo hvai hai | bahuro pheri dhaam nahi jaihai | 7 |","meaning_en":"They said: \"Even if we are cut to pieces, we shall not go back home again.\"","page":1379,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1379,"meaning_status":"draft"},{"type":"verse","number":[8],"number_text":"੮।","page":1379,"lines":[{"gurmukhi":"ਯਹੈ ਮੰਤ੍ਰ ਕਰਿ ਸੂਰਮਾ ਪਰੇ ਸੈਨ ਮੈ ਆਇ।","roman":"Yahai mantr kari soormaa pare sain mai aai |","meaning_en":"Having so resolved, the warriors came and fell upon the army;","page":1379,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਬਿਕ੍ਰਮ ਕੋ ਦਲੁ ਹੁਤੋ ਸੋ ਲੈ ਚਲੇ ਉਠਾਇ। ੮।","roman":"Jo bikram ko dalu huto so lai chale uthaai | 8 |","meaning_en":"the force that was Bikram's they swept away.","page":1379,"meaning_status":"draft","note":"ਲੈ ਚਲੇ ਉਠਾਇ: 'lifted and carried off', i.e. drove it back."}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":1381,"meaning_status":"draft"},{"type":"verse","number":[9],"number_text":"੯।","page":1381,"lines":[{"gurmukhi":"ਰਥੀ ਕੋਟਿ ਕੂਟੇ ਕਰੀ ਕ੍ਰੋਰਿ ਮਾਰੇ। ਕਿਤੇ ਸਾਜ ਔ ਰਾਜ ਬਾਜੀ ਬਿਦਾਰੇ।","roman":"Rathee koti koote karee krori maare | kite saaj au raaj baajee bidaare |","meaning_en":"Crores of charioteers were crushed and crores of elephants killed; many caparisoned and royal horses were torn apart.","page":1381,"meaning_status":"draft","note":"ਸਾਜ ਔ ਰਾਜ ਬਾਜੀ: 'horses with trappings and royal horses'; uncertain."},{"gurmukhi":"ਘਨੇ ਘੂਮਿ ਜੋਧਾ ਤਿਸੀ ਭੂਮਿ ਜੂਝੇ। ਕਹਾ ਲੌ ਗਨੌ ਮੈ ਨਹੀ ਜਾਤ ਬੂਝੇ। ੯।","roman":"Ghane ghoomi jodhaa tisee bhoomi joojhe | kahaa lau ganau mai nahee jaat boojhe | 9 |","meaning_en":"Many warriors reeled and fell fighting on that very ground; how far can I count them? They cannot be reckoned.","page":1381,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Ruaal metre.","page":1381,"meaning_status":"draft"},{"type":"verse","number":[10],"number_text":"੧੦।","page":1381,"lines":[{"gurmukhi":"ਅਮਿਤ ਸੈਨਾ ਲੈ ਚਲਿਯੋ ਤਹ ਆਪੁ ਰਾਜਾ ਸੰਗ।","roman":"Amit sainaa lai chaliyo tah aapu raajaa sang |","meaning_en":"The king himself marched there with a countless army,","page":1381,"meaning_status":"draft"},{"gurmukhi":"ਜੋਰਿ ਕੋਰਿ ਸੁ ਬੀਰ ਮੰਤ੍ਰੀ ਸਸਤ੍ਰ ਧਾਰਿ ਸੁਰੰਗਿ।","roman":"Jori kori su beer mantree sasatr dhaari surangi |","meaning_en":"having gathered crores of fine warriors and ministers, bearing weapons, brightly arrayed.","page":1381,"meaning_status":"draft","note":"ਸੁਰੰਗਿ: 'of fine colour', brightly arrayed; uncertain."},{"gurmukhi":"ਸੂਲ ਸੈਥਿਨ ਕੇ ਲਗੇ ਅਰੁ ਬੇਧਿ ਬਾਨਨ ਸਾਥ।","roman":"Sool saithin ke lage aru bedhi baanan saath |","meaning_en":"Struck by tridents and spears, and pierced with arrows,","page":1381,"meaning_status":"draft"},{"gurmukhi":"ਜੂਝਿ ਜੂਝਿ ਗਏ ਤਹਾ ਰਨ ਭੂਮਿ ਮਧਿ ਪ੍ਰਮਾਥ। ੧੦।","roman":"Joojhi joojhi gae tahaa ran bhoomi madhi pramaath | 10 |","meaning_en":"the mighty ones fell fighting there in the midst of the battlefield.","page":1381,"meaning_status":"draft","note":"ਪ੍ਰਮਾਥ: 'crushers', mighty warriors; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":1381,"meaning_status":"draft"},{"type":"verse","number":[11],"number_text":"੧੧।","page":1381,"lines":[{"gurmukhi":"ਜਗੇ ਜੰਗ ਜੋਧਾ ਗਏ ਜੂਝਿ ਭਾਰੇ। ਕਿਤੇ ਭੂਮਿ ਘੂਮੈ ਸੁ ਮਨੋ ਮਤਵਾਰੇ।","roman":"Jage jang jodhaa gae joojhi bhaare | kite bhoomi ghoomai su mano matvaare |","meaning_en":"Warriors roused to battle fell fighting, great ones; some reel upon the ground as if drunk.","page":1381,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤੇ ਮਾਰ ਹੀ ਮਾਰਿ ਐਸੇ ਪੁਕਾਰੈ। ਕਿਤੇ ਸਸਤ੍ਰ ਛੋਰੈ ਤ੍ਰਿਯਾ ਭੇਖ ਧਾਰੈ। ੧੧।","roman":"Kite maar hee maari aise pukaarai | kite sasatr chhorai triyaa bhekh dhaarai | 11 |","meaning_en":"Some cry out \"Kill! Kill!\"; some drop their weapons and put on women's dress.","page":1381,"meaning_status":"draft"}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":1381,"lines":[{"gurmukhi":"ਜਬੈ ਆਨਿ ਜੋਧਾ ਚਹੂੰ ਘਾਤ ਗਜੇ। ਮਹਾ ਸੰਖ ਔ ਦੁੰਦਭੀ ਨਾਦ ਵਜੇ।","roman":"Jabai aani jodhaa chahoon ghaat gaje | mahaa sankh au dundbhee naad vaje |","meaning_en":"When the warriors came and roared on all four sides, and great conches and kettledrums sounded,","page":1381,"meaning_status":"draft","note":"ਚਹੂੰ ਘਾਤ: 'on all four sides'; uncertain."},{"gurmukhi":"ਪਰੀ ਜੌ ਅਭੀਤਾਨ ਕੀ ਭੀਰ ਭਾਰੀ। ਤਬੈ ਆਪੁ ਸ੍ਰੀ ਕਾਲਿਕਾ ਕਿਲਕਾਰੀ। ੧੨।","roman":"Paree jau abheetaan kee bheer bhaaree | tabai aapu sree kaalikaa kilkaaree | 12 |","meaning_en":"when the great throng of the fearless closed in, then Sri Kalika herself shrieked.","page":1381,"meaning_status":"draft"}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":1381,"lines":[{"gurmukhi":"ਤਹਾ ਆਪੁ ਲੈ ਰੁਦ੍ਰ ਡੌਰੂ ਬਜਾਯੋ। ਚਤਰ ਸਾਠਿ ਮਿਲਿ ਜੋਗਨੀ ਗੀਤ ਗਾਯੋ।","roman":"Tahaa aapu lai rudr dauroo bajaayo | chatar saathi mili jognee geet gaayo |","meaning_en":"There Rudra himself took up his hand-drum and played it; the sixty-four Yoginis together sang songs.","page":1381,"meaning_status":"draft"},{"gurmukhi":"ਕਹੂੰ ਕੋਪਿ ਕੈ ਡਾਕਨੀ ਹਾਕ ਮਾਰੈ। ਕਹੂੰ ਭੂਤ ਔ ਪ੍ਰੇਤ ਨਾਗੇ ਬਿਹਾਰੈ। ੧੩।","roman":"Kahoon kopi kai daaknee haak maarai | kahoon bhoot au pret naage bihaarai | 13 |","meaning_en":"Somewhere Dakinis shout in anger; somewhere ghosts and spirits roam naked.","page":1381,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤੋਮਰ ਛੰਦ","roman":"Tomar chhand","meaning_en":"Tomar metre.","page":1381,"meaning_status":"draft"},{"type":"verse","number":[14],"number_text":"੧੪।","page":1381,"lines":[{"gurmukhi":"ਤਬ ਬਿਕ੍ਰਮੈ ਰਿਸਿ ਖਾਇ। ਭਟ ਭਾਤਿ ਭਾਤਿ ਬੁਲਾਇ।","roman":"Tab bikramai risi khaai | bhat bhaati bhaati bulaai |","meaning_en":"Then Bikram, filled with anger, summoned warriors of many kinds;","page":1381,"meaning_status":"draft"},{"gurmukhi":"ਚਿਤ ਮੈ ਅਧਿਕ ਹਠ ਠਾਨਿ। ਤਿਹ ਠਾ ਪਰਤ ਭੇ ਆਨਿ। ੧੪।","roman":"Chit mai adhik hath thaani | tih thaa parat bhe aani | 14 |","meaning_en":"with great resolve in their hearts, they came and fell upon that place.","page":1381,"meaning_status":"draft"}]},{"type":"verse","number":[15],"number_text":"੧੫।","page":1381,"lines":[{"gurmukhi":"ਅਤਿ ਤਹ ਸੁ ਜੋਧਾ ਆਨਿ। ਲਰਿ ਮਰਤ ਭੇ ਤਜਿ ਕਾਨਿ।","roman":"Ati tah su jodhaa aani | lari marat bhe taji kaani |","meaning_en":"Very many warriors came there and died fighting, casting aside all restraint,","page":1381,"meaning_status":"draft","note":"ਤਜਿ ਕਾਨਿ: 'abandoning regard/restraint'."},{"gurmukhi":"ਬਾਜੰਤ੍ਰ ਕੋਟਿ ਬਜਾਇ। ਰਨ ਰਾਗ ਮਾਰੂ ਗਾਇ। ੧੫।","roman":"Baajantr koti bajaai | ran raag maaroo gaai | 15 |","meaning_en":"sounding crores of instruments and singing the Maru raga in the battle.","page":1381,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1381,"meaning_status":"draft"},{"type":"verse","number":[16],"number_text":"੧੬।","page":1381,"lines":[{"gurmukhi":"ਆਨਿ ਪਰੇ ਤੇ ਸਕਲ ਨਿਬੇਰੇ। ਉਮਡੇ ਔਰ ਕਾਲ ਕੇ ਪ੍ਰੇਰੇ।","roman":"Aani pare te sakal nibere | umde aur kaal ke prere |","meaning_en":"Those who came and attacked were all finished off; others surged forward, driven on by Death.","page":1381,"meaning_status":"draft"},{"gurmukhi":"ਜੇ ਚਲਿ ਦਲ ਰਨ ਮੰਡਲ ਆਏ। ਲਰਿ ਮਰਿ ਕੈ ਸਭ ਸ੍ਵਰਗ ਸਿਧਾਏ। ੧੬।","roman":"Je chali dal ran mandal aae | lari mari kai sabh svarag sidhaae | 16 |","meaning_en":"The forces that came into the field of battle all fought, died and went to heaven.","page":1381,"meaning_status":"draft"}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":1381,"lines":[{"gurmukhi":"ਐਸੀ ਭਾਤਿ ਸੈਨ ਜਬ ਲਰਿਯੋ। ਏਕ ਬੀਰ ਜੀਯਤ ਨ ਉਬਰਿਯੋ।","roman":"Aisee bhaati sain jab lariyo | ek beer jeeyat na ubriyo |","meaning_en":"When the armies had fought in this way, not one warrior was left alive.","page":1381,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਹਠਿ ਰਾਵ ਆਪਿ ਦੋਊ ਧਾਏ। ਭਾਤਿ ਭਾਤਿ ਬਾਦਿਤ੍ਰ ਬਜਾਏ। ੧੭।","roman":"Tab hathi raav aapi do'oo dhaae | bhaati bhaati baaditr bajaae | 17 |","meaning_en":"Then the two kings themselves charged stubbornly, sounding instruments of many kinds.","page":1381,"meaning_status":"draft"}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":1381,"lines":[{"gurmukhi":"ਤੁਰਹੀ ਨਾਦ ਨਫੀਰੀ ਬਾਜੀ। ਸੰਖ ਢੋਲ ਕਰਨਾਏ ਗਾਜੀ।","roman":"Turhee naad napheeree baajee | sankh dhol karnaae gaajee |","meaning_en":"Trumpets and pipes sounded; conches, drums and war-horns roared.","page":1381,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਮੋ ਘੁਰੇ ਨਗਾਰੇ। ਦੇਖਤ ਸੁਰ ਬਿਵਾਨ ਚੜਿ ਸਾਰੇ। ੧੮।","roman":"Bhaati bhaati mo ghure nagaare | dekhat sur bivaan chari saare | 18 |","meaning_en":"Kettledrums of many kinds rumbled; all the gods watched, mounted on their aerial chariots.","page":1381,"meaning_status":"draft"}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":1383,"lines":[{"gurmukhi":"ਜੋ ਬਿਕ੍ਰਮਾ ਤਿਹ ਘਾਇ ਚਲਾਵੈ। ਆਪਿ ਆਨਿ ਸ੍ਰੀ ਚੰਡਿ ਬਚਾਵੈ।","roman":"Jo bikramaa tih ghaai chalaavai | aapi aani sree chandi bachaavai |","meaning_en":"Whatever blow Bikram aims at him, Sri Chandi herself comes and wards off.","page":1383,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਬ੍ਰਿਣ ਏਕ ਲਗਨ ਨਹਿ ਦੇਵੈ। ਸੇਵਕ ਜਾਨਿ ਰਾਖਿ ਕੈ ਲੇਵੈ। ੧੯।","roman":"Tih brin ek lagan nahi devai | sevak jaani raakhi kai levai | 19 |","meaning_en":"She does not let a single wound touch him; knowing him to be her servant she keeps him safe.","page":1383,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1383,"meaning_status":"draft"},{"type":"verse","number":[20],"number_text":"੨੦।","page":1383,"lines":[{"gurmukhi":"ਦੇਵੀ ਭਗਤ ਪਛਾਨਿ ਤਿਹ ਲਗਨ ਨ ਦੀਨੇ ਘਾਇ।","roman":"Devee bhagat pachhaani tih lagan na deene ghaai |","meaning_en":"Recognising him as her devotee, the goddess let no wound touch him,","page":1383,"meaning_status":"draft"},{"gurmukhi":"ਬਜ੍ਰ ਬਾਨ ਬਰਛੀਨ ਕੋ ਬਿਕ੍ਰਮ ਰਹਿਯੋ ਚਲਾਇ। ੨੦।","roman":"Bajr baan barchheen ko bikram rahiyo chalaai | 20 |","meaning_en":"though Bikram kept hurling thunderbolt-like arrows and spears.","page":1383,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1383,"meaning_status":"draft"},{"type":"verse","number":[21],"number_text":"੨੧।","page":1383,"lines":[{"gurmukhi":"ਸਾਲਬਾਹਨ ਕੀ ਇਕ ਪਟਰਾਨੀ। ਸੋ ਰਨ ਹੇਰਿ ਅਧਿਕ ਡਰਪਾਨੀ।","roman":"Saalbaahan kee ik patraanee | so ran heri adhik darpaanee |","meaning_en":"Salbahan had a chief queen; seeing the battle she was greatly afraid.","page":1383,"meaning_status":"draft"},{"gurmukhi":"ਪੂਜਿ ਗੌਰਜਾ ਤਾਹਿ ਮਨਾਈ। ਭੂਤ ਭਵਿਖ੍ਯ ਵਹੈ ਠਹਿਰਾਈ। ੨੧।","roman":"Pooji gaurjaa taahi manaaee | bhoot bhavikhy vahai thahiraaee | 21 |","meaning_en":"She worshipped Gauri and propitiated her, holding her to be the one who governs past and future.","page":1383,"meaning_status":"draft","note":"ਭੂਤ ਭਵਿਖ੍ਯ ਵਹੈ ਠਹਿਰਾਈ: 'she held her to be past and future'; exact sense uncertain."}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":1383,"lines":[{"gurmukhi":"ਤਬ ਤਿਹ ਦਰਸੁ ਗੌਰਜਾ ਦਯੋ। ਉਠਿ ਰਾਣੀ ਤਿਹ ਸੀਸ ਝੁਕਯੋ।","roman":"Tab tih darsu gaurjaa dayo | uthi raanee tih sees jhukyo |","meaning_en":"Then Gauri appeared to her; the queen rose and bowed her head to her.","page":1383,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਜਗਮਾਤ ਮਨਾਯੋ। ਜੀਤ ਹੋਇ ਹਮਰੀ ਬਰੁ ਪਾਯੋ। ੨੨।","roman":"Bhaati bhaati jagmaat manaayo | jeet hoi hamree baru paayo | 22 |","meaning_en":"She entreated the Mother of the World in many ways, and gained the boon: \"May the victory be ours.\"","page":1383,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1383,"meaning_status":"draft"},{"type":"verse","number":[23],"number_text":"੨੩।","page":1383,"lines":[{"gurmukhi":"ਸਾਲਬਾਹਨ ਬਿਕ੍ਰਮ ਭਏ ਬਾਜਿਯੋ ਲੋਹ ਅਪਾਰ।","roman":"Saalbaahan bikram bhae baajiyo loh apaar |","meaning_en":"Salbahan and Bikram met, and steel rang without limit;","page":1383,"meaning_status":"draft","note":"ਭਏ: 'were/came together'; a verb of meeting is understood."},{"gurmukhi":"ਆਠ ਜਾਮ ਆਹਵ ਬਿਖੈ ਜੁਧ ਭਯੋ ਬਿਕਰਾਰ। ੨੩।","roman":"Aath jaam aahav bikhai judh bhayo bikraar | 23 |","meaning_en":"for eight watches a dreadful fight raged in the battle.","page":1383,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1383,"meaning_status":"draft"},{"type":"verse","number":[24],"number_text":"੨੪।","page":1383,"lines":[{"gurmukhi":"ਸ੍ਯਾਲਕੋਟਿ ਨਾਯਕ ਰਿਸਿ ਭਰਿਯੋ। ਚਿਤ੍ਰ ਬਚਿਤ੍ਰ ਚੌਪਿ ਰਨ ਕਰਿਯੋ।","roman":"Syaalkoti naayak risi bhariyo | chitr bachitr chaupi ran kariyo |","meaning_en":"The lord of Sialkot, filled with rage, fought eagerly and wondrously.","page":1383,"meaning_status":"draft"},{"gurmukhi":"ਤਨਿ ਧਨ ਬਾਨ ਬਜ੍ਰ ਸੇ ਮਾਰੇ। ਰਾਵ ਬਿਕ੍ਰਮਾ ਸ੍ਵਰਗ ਸਿਧਾਰੇ। ੨੪।","roman":"Tani dhan baan bajr se maare | raav bikramaa svarag sidhaare | 24 |","meaning_en":"Drawing his bow he shot arrows like thunderbolts; King Bikram departed for heaven.","page":1383,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1383,"meaning_status":"draft"},{"type":"verse","number":[25],"number_text":"੨੫।","page":1383,"lines":[{"gurmukhi":"ਜੀਤਿ ਬਿਕ੍ਰਮਾਜੀਤ ਕੋ ਚਿਤ ਮੈ ਹਰਖ ਬਢਾਇ।","roman":"Jeeti bikramaajeet ko chit mai harakh badhaai |","meaning_en":"Having conquered Bikramajit, with joy swelling in his mind,","page":1383,"meaning_status":"draft"},{"gurmukhi":"ਅੰਤਹ ਪੁਰ ਆਵਤ ਭਯੋ ਅਧਿਕ ਹ੍ਰਿਦੈ ਸੁਖੁ ਪਾਇ। ੨੫।","roman":"Antah pur aavat bhayo adhik hridai sukhu paai | 25 |","meaning_en":"he came to the women's apartments with great happiness in his heart.","page":1383,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1383,"meaning_status":"draft"},{"type":"verse","number":[26],"number_text":"੨੬।","page":1383,"lines":[{"gurmukhi":"ਜਬ ਰਾਜਾ ਅੰਤਹ ਪੁਰ ਆਯੋ। ਸੁਨ੍ਯੋ ਜੁ ਬਰੁ ਰਾਨੀ ਜੂ ਪਾਯੋ।","roman":"Jab raajaa antah pur aayo | sunyo ju baru raanee joo paayo |","meaning_en":"When the king came to the women's apartments, he heard of the boon the queen had obtained.","page":1383,"meaning_status":"draft"},{"gurmukhi":"ਮੋ ਕੌ ਕਹਿਯੋ ਜੀਤਿ ਇਹ ਦਈ। ਤਾ ਸੌ ਪ੍ਰੀਤਿ ਅਧਿਕ ਹ੍ਵੈ ਗਈ। ੨੬।","roman":"Mo kau kahiyo jeeti ih daee | taa sau preeti adhik hvai gaee | 26 |","meaning_en":"He said, \"She has given me this victory\"; his love for her grew very great.","page":1383,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1383,"meaning_status":"draft"},{"type":"verse","number":[27],"number_text":"੨੭।","page":1383,"lines":[{"gurmukhi":"ਹਮਰੇ ਹਿਤ ਇਹ ਰਾਨਿਯੈ ਲੀਨੀ ਗੌਰਿ ਮਨਾਇ।","roman":"Hamre hit ih raaniyai leenee gauri manaai |","meaning_en":"\"For my sake this queen propitiated Gauri;","page":1383,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝਿ ਭਗੌਤੀ ਬਰੁ ਦਯੋ ਤਬ ਹਮ ਜਿਤੇ ਬਨਾਇ। ੨੭।","roman":"Reejhi bhagautee baru dayo tab ham jite banaai | 27 |","meaning_en":"Bhagauti, pleased, gave the boon, and so I won.\"","page":1383,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1383,"meaning_status":"draft"},{"type":"verse","number":[28],"number_text":"੨੮।","page":1383,"lines":[{"gurmukhi":"ਨਿਸ ਦਿਨ ਰਹੈ ਤਵਨ ਕੇ ਡੇਰੈ। ਔਰ ਰਾਨਿਯਨ ਓਰ ਨ ਹੇਰੈ।","roman":"Nis din rahai tavan ke derai | aur raaniyan or na herai |","meaning_en":"Night and day he stays in her quarters, and does not look toward the other queens.","page":1383,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਤ ਮਾਸ ਰਹਤੇ ਜਬ ਭਯੋ। ਦੇਬੀ ਪੂਤ ਏਕ ਤਿਹ ਦਯੋ। ੨੮।","roman":"Bahut maas rahte jab bhayo | debee poot ek tih dayo | 28 |","meaning_en":"When he had stayed many months, the goddess gave her a son.","page":1383,"meaning_status":"draft"}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":1385,"lines":[{"gurmukhi":"ਤਾ ਕੋ ਨਾਮ ਰਿਸਾਲੂ ਰਾਖਿਯੋ। ਐਸੋ ਬਚਨ ਚੰਡਿਕਾ ਭਾਖਿਯੋ।","roman":"Taa ko naam risaaloo raakhiyo | aiso bachan chandikaa bhaakhiyo |","meaning_en":"He was given the name Risalu; Chandika spoke these words:","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਜਤੀ ਜੋਧਾ ਇਹ ਹੋਈ। ਜਾ ਸਮ ਔਰ ਨ ਜਗ ਮੈ ਕੋਈ। ੨੯।","roman":"Mahaa jatee jodhaa ih hoee | jaa sam aur na jag mai koee | 29 |","meaning_en":"\"He will be a great celibate and warrior; there will be none other like him in the world.\"","page":1385,"meaning_status":"draft","note":"ਜਤੀ: one who keeps continence."}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":1385,"lines":[{"gurmukhi":"ਜ੍ਯੋ ਜ੍ਯੋ ਬਢਤ ਰਿਸਾਲੂ ਜਾਵੈ। ਨਿਤਿ ਅਖੇਟ ਕਰੈ ਮ੍ਰਿਗ ਘਾਵੈ।","roman":"Jyo jyo badhat risaaloo jaavai | niti akhet karai mrig ghaavai |","meaning_en":"As Risalu grows up, he goes hunting every day and kills deer.","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਸੈਰ ਦੇਸ ਦੇਸਨ ਕੋ ਕਰੈ। ਕਿਸਹੂ ਰਾਜਾ ਤੇ ਨਹਿ ਡਰੈ। ੩੦।","roman":"Sair des desan ko karai | kishoo raajaa te nahi darai | 30 |","meaning_en":"He travels through land after land, and fears no king.","page":1385,"meaning_status":"draft"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":1385,"lines":[{"gurmukhi":"ਖੇਲ ਅਖੇਟਕ ਜਬ ਗ੍ਰਿਹ ਆਵੈ। ਤਬ ਚੌਪਰ ਕੀ ਖੇਲਿ ਮਚਾਵੈ।","roman":"Khel akhetak jab grih aavai | tab chaupar kee kheli machaavai |","meaning_en":"When he comes home from the hunt, he sets up a game of chaupar.","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਜੀਤਿ ਚੀਤਿ ਰਾਜਨ ਕੌ ਲੇਈ। ਛੋਰਿ ਛੋਰਿ ਚਿਤ੍ਰ ਕਰਿ ਦੇਈ। ੩੧।","roman":"Jeeti cheeti raajan kau le'ee | chhori chhori chitr kari de'ee | 31 |","meaning_en":"He wins against kings, and lets each go after putting a mark on him.","page":1385,"meaning_status":"draft","note":"ਜੀਤਿ ਚੀਤਿ: 'winning' (echo-word). ਛੋਰਿ ਛੋਰਿ ਚਿਤ੍ਰ ਕਰਿ ਦੇਈ: 'releases them after making a mark/picture', or 'leaves them amazed'; uncertain."}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":1385,"lines":[{"gurmukhi":"ਏਕ ਡੋਮ ਤਾ ਕੋ ਗ੍ਰਿਹ ਆਯੋ। ਖੇਲ ਰਿਸਾਲੂ ਸਾਥ ਰਚਾਯੋ।","roman":"Ek dom taa ko grih aayo | khel risaaloo saath rachaayo |","meaning_en":"A Dom came to his house and set up a game with Risalu.","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਪਗਿਯਾ ਬਸਤ੍ਰ ਅਸ੍ਵ ਜਬ ਹਾਰੇ। ਚਿਤ੍ਰ ਚਿਤ ਯੌ ਬਚਨ ਉਚਾਰੇ। ੩੨।","roman":"Pagiyaa basatr asv jab haare | chitr chit yau bachan uchaare | 32 |","meaning_en":"When he had lost his turban, clothes and horse, he spoke these words with a cunning mind:","page":1385,"meaning_status":"draft","note":"ਡੋਮ: a minstrel caste. ਚਿਤ੍ਰ ਚਿਤ: 'with a clever (or wondering) mind'; uncertain."}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":1385,"lines":[{"gurmukhi":"ਚੌਪਰ ਬਾਜ ਤੋਹਿ ਤਬ ਜਾਨੋ। ਮੇਰੋ ਕਹਿਯੋ ਏਕ ਤੁਮ ਮਾਨੋ।","roman":"Chaupar baaj tohi tab jaano | mero kahiyo ek tum maano |","meaning_en":"\"I shall count you a chaupar player only if you accept one thing I say:","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਸਿਰਕਪ ਕੇ ਸੰਗ ਖੇਲ ਰਚਾਵੋ। ਤਬ ਇਹ ਖੇਲ ਜੀਤਿ ਗ੍ਰਿਹ ਆਵੋ। ੩੩।","roman":"Sirkap ke sang khel rachaavo | tab ih khel jeeti grih aavo | 33 |","meaning_en":"set up a game with Sirkap; then win that game and come home.\"","page":1385,"meaning_status":"draft"}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":1385,"lines":[{"gurmukhi":"ਯੌ ਸੁਣ ਬਚਨ ਰਿਸਾਲੂ ਧਾਯੋ। ਚੜਿ ਘੋਰਾ ਪੈ ਤਹੀ ਸਿਧਾਯੋ।","roman":"Yau sun bachan risaaloo dhaayo | chari ghoraa pai tahee sidhaayo |","meaning_en":"Hearing these words Risalu set out; mounting his horse he went straight there.","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਸਿਰਕਪ ਕੇ ਦੇਸੰਤਰ ਆਯੋ। ਆਨਿ ਰਾਵ ਸੌ ਖੇਲ ਰਚਾਯੋ। ੩੪।","roman":"Sirkap ke desantar aayo | aani raav sau khel rachaayo | 34 |","meaning_en":"He came to Sirkap's country, and set up a game with that king.","page":1385,"meaning_status":"draft"}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":1385,"lines":[{"gurmukhi":"ਤਬ ਸਿਰਕਪ ਛਲ ਅਧਿਕ ਸੁ ਧਾਰੇ। ਸਸਤ੍ਰ ਅਸਤ੍ਰ ਬਸਤ੍ਰਨ ਜੁਤ ਹਾਰੇ।","roman":"Tab sirkap chhal adhik su dhaare | sasatr asatr bastran jut haare |","meaning_en":"Then Sirkap used much trickery, yet he lost his weapons, arms and clothes as well.","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਧਨ ਹਰਾਇ ਸਿਰ ਬਾਜੀ ਲਾਗੀ। ਸੋਊ ਜੀਤਿ ਲਈ ਬਡਭਾਗੀ। ੩੫।","roman":"Dhan haraai sir baajee laagee | so'oo jeeti laee badbhaagee | 35 |","meaning_en":"Having lost his wealth he staked his head; that too the fortunate one won.","page":1385,"meaning_status":"draft"}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":1385,"lines":[{"gurmukhi":"ਜੀਤਿ ਤਾਹਿ ਮਾਰਨ ਲੈ ਧਾਯੋ। ਯੌ ਸੁਨਿ ਕੈ ਰਨਿਵਾਸਹਿ ਪਾਯੋ।","roman":"Jeeti taahi maaran lai dhaayo | yau suni kai ranivaashi paayo |","meaning_en":"Having won he took him off to kill him; then he heard this from the queens' apartments:","page":1385,"meaning_status":"draft","note":"ਯੌ ਸੁਨਿ ਕੈ ਰਨਿਵਾਸਹਿ ਪਾਯੋ: read as 'he heard this from the women's quarters'; uncertain."},{"gurmukhi":"ਯਾ ਕੀ ਸੁਤਾ ਕੋਕਿਲਾ ਲੀਜੈ। ਜਿਯ ਤੇ ਬਧ ਯਾ ਕੌ ਨਹਿ ਕੀਜੈ। ੩੬।","roman":"Yaa kee sutaa kokilaa leejai | jiy te badh yaa kau nahi keejai | 36 |","meaning_en":"\"Take his daughter Kokila; do not put him to death.\"","page":1385,"meaning_status":"draft"}]},{"type":"verse","number":[37],"number_text":"੩੭।","page":1385,"lines":[{"gurmukhi":"ਤਬ ਤਿਹ ਜਾਨ ਮਾਫ ਕੈ ਦਈ। ਤਾ ਕੀ ਸੁਤਾ ਕੋਕਿਲਾ ਲਈ।","roman":"Tab tih jaan maaph kai daee | taa kee sutaa kokilaa laee |","meaning_en":"Then he spared his life, and took his daughter Kokila.","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਦੰਡਕਾਰ ਮੈ ਸਦਨ ਸਵਾਰਿਯੋ। ਤਾ ਕੇ ਬੀਚ ਰਾਖ ਤਿਹ ਧਾਰਿਯੋ। ੩੭।","roman":"Dandkaar mai sadan savaariyo | taa ke beech raakh tih dhaariyo | 37 |","meaning_en":"He built a house in the Dandak forest, and kept her within it.","page":1385,"meaning_status":"draft","note":"ਦੰਡਕਾਰ: read as Dandakaranya, the Dandak forest."}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":1385,"lines":[{"gurmukhi":"ਤਾ ਕੌ ਲਰਿਕਾਪਨ ਜਬ ਗਯੋ। ਜੋਬਨ ਆਨਿ ਦਮਾਮੋ ਦਯੋ।","roman":"Taa kau larikaapan jab gayo | joban aani damaamo dayo |","meaning_en":"When her childhood had passed, and youth came and beat its drum,","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜਾ ਨਿਕਟ ਨ ਤਾ ਕੇ ਆਵੈ। ਯਾ ਤੇ ਅਤਿ ਰਾਨੀ ਦੁਖੁ ਪਾਵੇ। ੩੮।","roman":"Raajaa nikat na taa ke aavai | yaa te ati raanee dukhu paave | 38 |","meaning_en":"the king did not come near her; at this the queen suffered greatly.","page":1385,"meaning_status":"draft"}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":1385,"lines":[{"gurmukhi":"ਏਕ ਦਿਵਸ ਰਾਜਾ ਜਬ ਆਯੋ। ਤਬ ਰਾਨੀ ਯੌ ਬਚਨ ਸੁਨਾਯੋ।","roman":"Ek divas raajaa jab aayo | tab raanee yau bachan sunaayo |","meaning_en":"One day when the king came, the queen spoke these words:","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਹਮ ਕੋ ਲੈ ਤੁਮ ਸੰਗ ਸਿਧਾਰੌ। ਬਨ ਮੈ ਜਹਾ ਮ੍ਰਿਗਨ ਕੌ ਮਾਰੌ। ੩੯।","roman":"Ham ko lai tum sang sidhaarau | ban mai jahaa mrigan kau maarau | 39 |","meaning_en":"\"Take me along with you to the forest where you kill the deer.\"","page":1385,"meaning_status":"draft"}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":1385,"lines":[{"gurmukhi":"ਲੈ ਰਾਜਾ ਤਿਹ ਸੰਗ ਸਿਧਾਯੋ। ਜਹ ਮ੍ਰਿਗ ਹਨਤ ਹੇਤ ਤਹ ਆਯੋ।","roman":"Lai raajaa tih sang sidhaayo | jah mrig hanat het tah aayo |","meaning_en":"The king took her with him, and came where he went to kill deer.","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਦੈ ਫੇਰਾ ਸਰ ਸੌ ਮ੍ਰਿਗ ਮਾਰਿਯੋ। ਯਹ ਕੌਤਕ ਕੋਕਿਲਾ ਨਿਹਾਰਿਯੋ। ੪੦।","roman":"Dai pheraa sar sau mrig maariyo | yah kautak kokilaa nihaariyo | 40 |","meaning_en":"Wheeling it round, he killed a deer with an arrow; Kokila watched this feat.","page":1385,"meaning_status":"draft","note":"ਦੈ ਫੇਰਾ: 'giving a turn', chasing it round; uncertain."}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":1385,"lines":[{"gurmukhi":"ਤਬ ਰਾਨੀ ਯੌ ਬਚਨ ਉਚਾਰੇ। ਸੁਨੋ ਬਾਤ ਨ੍ਰਿਪ ਨਾਥ ਹਮਾਰੇ।","roman":"Tab raanee yau bachan uchaare | suno baat nrip naath hamaare |","meaning_en":"Then the queen spoke thus: \"Hear me, my lord king:","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਦ੍ਰਿਗ ਸਰ ਸੋ ਮ੍ਰਿਗ ਕੋ ਹੌ ਮਾਰੌ। ਤੁਮ ਠਾਢੇ ਯਹ ਚਰਿਤ ਨਿਹਾਰੋ। ੪੧।","roman":"Drig sar so mrig ko hau maarau | tum thaadhe yah charit nihaaro | 41 |","meaning_en":"I shall kill a deer with the arrows of my eyes; stand and watch this feat.\"","page":1385,"meaning_status":"draft"}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":1385,"lines":[{"gurmukhi":"ਘੂੰਘਟ ਛੋਰਿ ਕੋਕਿਲਾ ਧਾਈ। ਮ੍ਰਿਗ ਲਖਿ ਤਾਹਿ ਗਯੋ ਉਰਝਾਈ।","roman":"Ghoonghat chhori kokilaa dhaaee | mrig lakhi taahi gayo urjhaaee |","meaning_en":"Throwing back her veil Kokila ran forward; the deer, seeing her, was entranced.","page":1385,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਰੂਪ ਜਬ ਤਾਹਿ ਨਿਹਾਰਿਯੋ। ਠਾਢਿ ਰਹਿਯੋ ਨਹਿ ਸੰਕ ਪਧਾਰਿਯੋ। ੪੨।","roman":"Amit roop jab taahi nihaariyo | thaadhi rahiyo nahi sank padhaariyo | 42 |","meaning_en":"When it saw her boundless beauty it stood still, and did not move off in fear.","page":1385,"meaning_status":"draft"}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":1387,"lines":[{"gurmukhi":"ਕਰ ਸੌ ਮ੍ਰਿਗ ਰਾਨੀ ਜਬ ਗਹਿਯੋ। ਯਹ ਕੌਤਕ ਰੀਸਾਲੂ ਲਹਿਯੋ।","roman":"Kar sau mrig raanee jab gahiyo | yah kautak reesaaloo lahiyo |","meaning_en":"When the queen caught the deer with her hand, Risalu saw this marvel.","page":1387,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਚਿਤ ਭੀਤਰ ਅਧਿਕ ਰਿਸਾਯੋ। ਕਾਨ ਕਾਟ ਕੈ ਤਾਹਿ ਪਠਾਯੋ। ੪੩।","roman":"Tab chit bheetar adhik risaayo | kaan kaat kai taahi pathaayo | 43 |","meaning_en":"Then he grew very angry in his heart; he cut off its ears and sent it away.","page":1387,"meaning_status":"draft"}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":1387,"lines":[{"gurmukhi":"ਕਾਨ ਕਟਿਯੋ ਮ੍ਰਿਗ ਲਖਿ ਜਬ ਪਾਯੋ। ਸੋ ਹੋਡੀ ਮਹਲਨ ਤਰ ਆਯੋ।","roman":"Kaan katiyo mrig lakhi jab paayo | so hodee mahlan tar aayo |","meaning_en":"The deer with its ears cut came beneath the palace of Hodi; when he caught sight of it,","page":1387,"meaning_status":"draft"},{"gurmukhi":"ਸਿੰਧ ਦੇਸ ਏਸ੍ਵਰ ਗਹਿ ਲਯੋ। ਚੜਿ ਘੋੜਾ ਪੈ ਪਾਛੇ ਧਯੋ। ੪੪।","roman":"Sindh des esvar gahi layo | chari ghoraa pai paachhe dhayo | 44 |","meaning_en":"the lord of the land of Sindh took up the chase; mounting his horse he ran after it.","page":1387,"meaning_status":"draft","note":"ਗਹਿ ਲਯੋ: 'seized'; read here as taking up the pursuit; uncertain."}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":1387,"lines":[{"gurmukhi":"ਤਬ ਆਗੇ ਤਾ ਕੇ ਮ੍ਰਿਗ ਧਾਯੋ। ਮਹਲ ਕੋਕਿਲਾ ਕੇ ਤਰ ਆਯੋ।","roman":"Tab aage taa ke mrig dhaayo | mahal kokilaa ke tar aayo |","meaning_en":"Then the deer ran on ahead of him, and came beneath Kokila's palace.","page":1387,"meaning_status":"draft"},{"gurmukhi":"ਹੋਡੀ ਤਾ ਕੋ ਰੂਪ ਨਿਹਾਰਿਯੋ। ਹਰਿ ਅਰਿ ਸਰ ਤਾ ਕੌ ਤਨੁ ਮਾਰਿਯੋ। ੪੫।","roman":"Hodee taa ko roop nihaariyo | hari ari sar taa kau tanu maariyo | 45 |","meaning_en":"Hodi beheld her beauty; the god of love struck his body with an arrow.","page":1387,"meaning_status":"draft","note":"ਹਰਿ ਅਰਿ: read as 'the enemy of Har (Shiva)', i.e. Kamdev; uncertain."}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":1387,"lines":[{"gurmukhi":"ਹੋਡੀ ਜਬ ਕੋਕਿਲਾ ਨਿਹਾਰੀ। ਬਿਹਸਿ ਬਾਤ ਇਹ ਭਾਤਿ ਉਚਾਰੀ।","roman":"Hodee jab kokilaa nihaaree | bihsi baat ih bhaati uchaaree |","meaning_en":"When Kokila saw Hodi, she smiled and spoke in this way:","page":1387,"meaning_status":"draft","note":"Could also be read 'when Hodi saw Kokila, he smiled and said'; the speaker is not certain."},{"gurmukhi":"ਹਮ ਤੁਮ ਆਉ ਬਿਰਾਜਹਿੰ ਦੋਊ। ਜਾ ਕੋ ਭੇਦ ਨ ਪਾਵਤ ਕੋਊ। ੪੬।","roman":"Ham tum aau biraajhin do'oo | jaa ko bhed na paavat ko'oo | 46 |","meaning_en":"\"Come, let us two take our pleasure together, so that no one learns the secret.\"","page":1387,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":1387,"lines":[{"gurmukhi":"ਹੈ ਤੇ ਉਤਰ ਭਵਨ ਪਗ ਧਾਰਿਯੋ। ਆਨਿ ਕੋਕਿਲਾ ਸਾਥ ਬਿਹਾਰਿਯੋ।","roman":"Hai te utar bhavan pag dhaariyo | aani kokilaa saath bihaariyo |","meaning_en":"Dismounting from his horse he stepped into the house, and came and sported with Kokila.","page":1387,"meaning_status":"draft"},{"gurmukhi":"ਭੋਗ ਕਮਾਇ ਬਹੁਰਿ ਉਠ ਗਯੋ। ਦੁਤਯ ਦਿਵਸ ਪੁਨਿ ਆਵਤ ਭਯੋ। ੪੭।","roman":"Bhog kamaai bahuri uth gayo | dutay divas puni aavat bhayo | 47 |","meaning_en":"Having lain with her he rose and left; the next day he came again.","page":1387,"meaning_status":"draft"}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":1387,"lines":[{"gurmukhi":"ਤਬ ਮੈਨਾ ਯਹ ਭਾਤਿ ਬਖਾਨੀ। ਕਾ ਕੋਕਿਲਾ ਤੂ ਭਈ ਅਯਾਨੀ।","roman":"Tab mainaa yah bhaati bakhaanee | kaa kokilaa too bhaee ayaanee |","meaning_en":"Then the mynah spoke thus: \"Kokila, why have you turned foolish?\"","page":1387,"meaning_status":"draft"},{"gurmukhi":"ਯੌ ਸੁਨਿ ਬੈਨ ਤਾਹਿ ਹਨਿ ਡਾਰਿਯੋ। ਤਬ ਸੁਕ ਤਿਹ ਇਹ ਭਾਤਿ ਉਚਾਰਿਯੋ। ੪੮।","roman":"Yau suni bain taahi hani daariyo | tab suk tih ih bhaati uchaariyo | 48 |","meaning_en":"Hearing these words she killed it; then the parrot spoke to her in this way:","page":1387,"meaning_status":"draft"}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":1387,"lines":[{"gurmukhi":"ਭਲੋ ਕਰਿਯੋ ਮੈਨਾ ਤੈ ਮਾਰੀ। ਸਿੰਧ ਏਸ ਕੇ ਸਾਥ ਬਿਹਾਰੀ।","roman":"Bhalo kariyo mainaa tai maaree | sindh es ke saath bihaaree |","meaning_en":"\"You did well to kill the mynah, and to sport with the lord of Sindh.","page":1387,"meaning_status":"draft"},{"gurmukhi":"ਮੋਕਹ ਕਾਢਿ ਹਾਥ ਪੈ ਲੀਜੈ। ਬੀਚ ਪਿੰਜਰਾ ਰਹਨ ਨ ਦੀਜੈ। ੪੯।","roman":"Mokah kaadhi haath pai leejai | beech pinjraa rahan na deejai | 49 |","meaning_en":"Take me out upon your hand; do not leave me inside the cage.","page":1387,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"Sortha.","page":1387,"meaning_status":"draft"},{"type":"verse","number":[50],"number_text":"੫੦।","page":1387,"lines":[{"gurmukhi":"ਜਿਨਿ ਰੀਸਾਲੂ ਧਾਇ ਇਹ ਠਾ ਪਹੁੰਚੈ ਆਇ ਕੈ।","roman":"Jini reesaaloo dhaai ih thaa pahunchai aai kai |","meaning_en":"Lest Risalu come running and arrive at this place,","page":1387,"meaning_status":"draft"},{"gurmukhi":"ਮੁਹਿ ਤੁਹਿ ਸਿੰਧੁ ਬਹਾਇ ਜਮਪੁਰ ਦੇਇ ਪਠਾਇ ਲਖਿ। ੫੦।","roman":"Muhi tuhi sindhu bahaai jampur dei pathaai lakhi | 50 |","meaning_en":"and, seeing this, throw me and you in the river and send us to Yama's city.\"","page":1387,"meaning_status":"draft","note":"ਸਿੰਧੁ: 'the river' (or the Indus)."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1387,"meaning_status":"draft"},{"type":"verse","number":[51],"number_text":"੫੧।","page":1387,"lines":[{"gurmukhi":"ਤਬ ਤਿਹ ਕਾਢਿ ਹਾਥ ਪੈ ਲਯੋ। ਦ੍ਰਿਸਟਿ ਚੁਕਾਇ ਸੂਆ ਉਡਿ ਗਯੋ।","roman":"Tab tih kaadhi haath pai layo | dristi chukaai sooaa udi gayo |","meaning_en":"Then she took it out upon her hand; evading her eye, the parrot flew away.","page":1387,"meaning_status":"draft"},{"gurmukhi":"ਜਾਇ ਰਿਸਾਲੂ ਸਾਥ ਜਤਾਯੋ। ਖੇਲਤ ਕਹਾ ਚੋਰ ਗ੍ਰਿਹ ਆਯੋ। ੫੧।","roman":"Jaai risaaloo saath jataayo | khelat kahaa chor grih aayo | 51 |","meaning_en":"It went and informed Risalu: \"Why are you at sport? A thief has come into your house.\"","page":1387,"meaning_status":"draft"}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":1387,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਬੈਨਿ ਰਿਸਾਲੂ ਧਾਯੋ। ਤੁਰਤੁ ਧੌਲਹਰ ਕੇ ਤਟ ਆਯੋ।","roman":"Yau suni baini risaaloo dhaayo | turtu dhaulhar ke tat aayo |","meaning_en":"Hearing these words Risalu hastened, and at once came to the foot of the palace.","page":1387,"meaning_status":"draft"},{"gurmukhi":"ਭੇਦ ਕੋਕਿਲਾ ਜਬ ਲਖਿ ਪਾਯੋ। ਸਫ ਕੇ ਬਿਖੈ ਲਪੇਟਿ ਦੁਰਾਯੋ। ੫੨।","roman":"Bhed kokilaa jab lakhi paayo | saph ke bikhai lapeti duraayo | 52 |","meaning_en":"When Kokila realised this, she rolled him up in a mat and hid him.","page":1387,"meaning_status":"draft","note":"'him': Hodi. ਸਫ: a mat."}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":1387,"lines":[{"gurmukhi":"ਕਹਿਯੋ ਬਕਤ੍ਰ ਫੀਕੌ ਕਿਯੋ ਭਯੋ। ਜਨੁ ਕਰਿ ਰਾਹੁ ਲੂਟਿ ਸਸਿ ਲਯੋ।","roman":"Kahiyo bakatr pheekau kiyo bhayo | janu kari raahu looti sasi layo |","meaning_en":"He said: \"Why has your face grown pale, as if Rahu had plundered the moon?","page":1387,"meaning_status":"draft"},{"gurmukhi":"ਅੰਬੁਯਨ ਕੀ ਅੰਬਿਆ ਕਿਨ ਹਰੀ। ਢੀਲੀ ਸੇਜ ਕਹੋ ਕਿਹ ਕਰੀ। ੫੩।","roman":"Anbuyan kee anbiaa kin haree | dheelee sej kaho kih karee | 53 |","meaning_en":"Who has taken the young mangoes from the mango trees? Tell me, who has slackened the bed?\"","page":1387,"meaning_status":"draft","note":"ਅੰਬੁਯਨ ਕੀ ਅੰਬਿਆ: read as 'the young mangoes of the mango trees'; it may instead be a figure for the bloom of her lotus-eyes; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1389,"meaning_status":"draft"},{"type":"verse","number":[54],"number_text":"੫੪।","page":1389,"lines":[{"gurmukhi":"ਜਬ ਤੇ ਗਏ ਅਖੇਟ ਤੁਮ ਤਬ ਤੇ ਮੈ ਦੁਖ ਪਾਇ।","roman":"Jab te gae akhet tum tab te mai dukh paai |","meaning_en":"\"Ever since you went hunting, I have been in pain;","page":1389,"meaning_status":"draft"},{"gurmukhi":"ਘਾਯਲ ਜ੍ਯੋ ਘੂੰਮਤ ਰਹੀ ਬਿਨਾ ਤਿਹਾਰੇ ਰਾਇ। ੫੪।","roman":"Ghaayal jyo ghoonmat rahee binaa tihaare raai | 54 |","meaning_en":"I have wandered about like one wounded, without you, O king.","page":1389,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1389,"meaning_status":"draft"},{"type":"verse","number":[55],"number_text":"੫੫।","page":1389,"lines":[{"gurmukhi":"ਬਾਤ ਬਹੀ ਅੰਬਿਯਨ ਲੈ ਗਈ। ਮੋ ਤਨ ਮੈਨੁਪਜਾਵਤਿ ਭਈ।","roman":"Baat bahee anbiyan lai gaee | mo tan mainupjaavti bhaee |","meaning_en":"The wind blew and carried off the young mangoes; and it roused desire in my body.","page":1389,"meaning_status":"draft","note":"ਮੈਨੁਪਜਾਵਤਿ: read as ਮੈਨ ਉਪਜਾਵਤਿ, 'gave rise to desire (Kamdev)'."},{"gurmukhi":"ਤਬ ਮੈ ਲਏ ਅਧਿਕ ਪਸਵਾਰੇ। ਜੈਸੇ ਮ੍ਰਿਗ ਸਾਯਕ ਕੇ ਮਾਰੇ। ੫੫।","roman":"Tab mai lae adhik pasvaare | jaise mrig saayak ke maare | 55 |","meaning_en":"Then I tossed from side to side many times, like a deer struck by an arrow.","page":1389,"meaning_status":"draft"}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":1389,"lines":[{"gurmukhi":"ਤਾ ਤੇ ਲਰੀ ਮੋਤਿਯਨ ਛੂਟੀ। ਉਡਗ ਸਹਿਤ ਨਿਸਿ ਜਨੁ ਰਵਿ ਟੂਟੀ।","roman":"Taa te laree motiyan chhootee | udag sahit nisi janu ravi tootee |","meaning_en":"From that my string of pearls broke, like the night with its stars broken up by the sun.","page":1389,"meaning_status":"draft","note":"ਉਡਗ ਸਹਿਤ ਨਿਸਿ ਜਨੁ ਰਵਿ ਟੂਟੀ: sense of the simile uncertain."},{"gurmukhi":"ਹੌ ਅਤਿ ਦਖਿਤ ਮੈਨ ਸੌ ਭਈ। ਯਾ ਤੇ ਸੇਜ ਢੀਲ ਹ੍ਵੈ ਗਈ। ੫੬।","roman":"Hau ati dakhit main sau bhaee | yaa te sej dheel hvai gaee | 56 |","meaning_en":"I was sorely troubled by desire; that is why the bed became slack.\"","page":1389,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1389,"meaning_status":"draft"},{"type":"verse","number":[57],"number_text":"੫੭।","page":1389,"lines":[{"gurmukhi":"ਤਵ ਦਰਸਨ ਲਖਿ ਚਿਤ ਕੋ ਮਿਟਿ ਗਯੋ ਸੋਕ ਅਪਾਰ।","roman":"Tav darsan lakhi chit ko miti gayo sok apaar |","meaning_en":"\"On seeing you, the boundless sorrow of my heart is gone,","page":1389,"meaning_status":"draft"},{"gurmukhi":"ਜ੍ਯੋ ਚਕਵੀ ਪਤਿ ਆਪਨੇ ਦਿਵਕਰ ਨੈਨ ਨਿਹਾਰ। ੫੭।","roman":"Jyo chakvee pati aapne divkar nain nihaar | 57 |","meaning_en":"like the chakvi when her eyes behold the sun, and her own mate.\"","page":1389,"meaning_status":"draft","note":"The chakvi (ruddy sheldrake hen) is said to be parted from her mate at night and reunited at sunrise. Construction uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1389,"meaning_status":"draft"},{"type":"verse","number":[58],"number_text":"੫੮।","page":1389,"lines":[{"gurmukhi":"ਯੌ ਰਾਜਾ ਰਾਨੀ ਬਰਮਾਯੋ। ਘਰੀਕ ਬਾਤਨ ਸੋ ਉਰਝਾਯੋ।","roman":"Yau raajaa raanee barmaayo | ghareek baatan so urjhaayo |","meaning_en":"Thus the queen beguiled the king, and kept him entangled in talk for a while.","page":1389,"meaning_status":"draft"},{"gurmukhi":"ਪੁਨਿ ਤਾ ਸੌ ਇਹ ਭਾਤਿ ਉਚਾਰੋ। ਸੁਨੋ ਰਾਵ ਜੂ ਬਚਨ ਹਮਾਰੋ। ੫੮।","roman":"Puni taa sau ih bhaati uchaaro | suno raav joo bachan hamaaro | 58 |","meaning_en":"Then she spoke to him in this way: \"Hear my words, O king:","page":1389,"meaning_status":"draft"}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":1389,"lines":[{"gurmukhi":"ਹਮ ਤੁਮ ਕਰ ਮੇਵਾ ਦੋਊ ਲੇਹੀ। ਡਾਰਿ ਡਾਰਿ ਯਾ ਸਫ ਮੈ ਦੇਹੀ।","roman":"Ham tum kar mevaa do'oo lehee | daari daari yaa saph mai dehee |","meaning_en":"let us both take dried fruits in our hands, and throw them one by one into this mat.","page":1389,"meaning_status":"draft"},{"gurmukhi":"ਹਮ ਦੋਊ ਦਾਵ ਇਹੈ ਬਦ ਡਾਰੈ। ਸੋ ਹਾਰੈ ਜਿਹ ਪਰੈ ਕਿਨਾਰੈ। ੫੯।","roman":"Ham do'oo daav ihai bad daarai | so haarai jih parai kinaarai | 59 |","meaning_en":"Let us both lay this wager: the one whose throw falls at the edge loses.\"","page":1389,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1389,"meaning_status":"draft"},{"type":"verse","number":[60],"number_text":"੬੦।","page":1389,"lines":[{"gurmukhi":"ਤਬ ਦੁਹੂੰਅਨ ਮੇਵਾ ਲਯੋ ਐਸੇ ਬੈਨ ਬਖਾਨਿ।","roman":"Tab duhoonan mevaa layo aise bain bakhaani |","meaning_en":"Then both took dried fruits, having spoken such words;","page":1389,"meaning_status":"draft"},{"gurmukhi":"ਚਤੁਰਿ ਨ੍ਰਿਪਤਿ ਅਤਿ ਚਿਤ ਹੁਤੋ ਇਹੀ ਬੀਚ ਗਯੋ ਜਾਨਿ। ੬੦।","roman":"Chaturi nripti ati chit huto ihee beech gayo jaani | 60 |","meaning_en":"the king was very shrewd of mind, and in the course of this he understood.","page":1389,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1389,"meaning_status":"draft"},{"type":"verse","number":[61],"number_text":"੬੧।","page":1389,"lines":[{"gurmukhi":"ਤਬ ਰਾਜੈ ਇਹ ਬਚਨ ਉਚਾਰੀ। ਸੁਨੁ ਰਾਨੀ ਕੋਕਿਲਾ ਪਿਆਰੀ।","roman":"Tab raajai ih bachan uchaaree | sunu raanee kokilaa piaaree |","meaning_en":"Then the king spoke these words: \"Listen, Queen Kokila, my dear:","page":1389,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਹਰਾਇ ਮ੍ਰਿਗਹਿ ਮੈ ਆਯੋ। ਕੰਪਤ ਬੂਟ ਮੈ ਦੁਰਿਯੋ ਡਰਾਯੋ। ੬੧।","roman":"Ek haraai mrighi mai aayo | kanpat boot mai duriyo daraayo | 61 |","meaning_en":"I have come after wearing down a deer; trembling, it has hidden in a bush in fear.\"","page":1389,"meaning_status":"draft","note":"ਹਰਾਇ: 'having defeated/exhausted'. ਬੂਟ: bush."}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":1389,"lines":[{"gurmukhi":"ਹੌਡੀ ਬਾਤ ਮੂੰਡ ਇਹ ਆਨੀ। ਮ੍ਰਿਗ ਪੈ ਕਰਿ ਕੋਕਿਲਾ ਪਛਾਨੀ।","roman":"Haudee baat moond ih aanee | mrig pai kari kokilaa pachhaanee |","meaning_en":"He brought this talk round upon Hodi's head, but Kokila took it to be about a deer.","page":1389,"meaning_status":"draft","note":"ਹੌਡੀ ਬਾਤ ਮੂੰਡ ਇਹ ਆਨੀ: 'he laid this talk on Hodi's head', i.e. he meant Hodi; uncertain."},{"gurmukhi":"ਕਹੇ ਤੌ ਤੁਰਤ ਤਾਹਿ ਹਨਿ ਲ੍ਯਾਊ। ਤਾ ਕੋ ਤੁਮ ਕੋ ਮਾਸੁ ਖਵਾਊ। ੬੨।","roman":"Kahe tau turat taahi hani lyaaoo | taa ko tum ko maasu khavaaoo | 62 |","meaning_en":"\"If you say so, I shall kill it at once and bring it, and feed you its meat.\"","page":1389,"meaning_status":"draft"}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":1389,"lines":[{"gurmukhi":"ਤਬ ਕੋਕਿਲਾ ਖੁਸੀ ਹ੍ਵੈ ਗਈ। ਚਾਹਤ ਥੀ ਚਿਤ ਮੈ ਸੋ ਭਈ।","roman":"Tab kokilaa khusee hvai gaee | chaahat thee chit mai so bhaee |","meaning_en":"Then Kokila was glad; what she wished in her heart had come about.","page":1389,"meaning_status":"draft"},{"gurmukhi":"ਯਹ ਇਨ ਮੂੜ ਭੇਦ ਨਹਿ ਪਾਯੋ। ਤਜਿ ਯਾ ਕੌ ਮ੍ਰਿਗ ਕੋ ਤਬ ਧਾਯੋ। ੬੩।","roman":"Yah in moor bhed nahi paayo | taji yaa kau mrig ko tab dhaayo | 63 |","meaning_en":"\"This fool has not grasped the secret,\" she thought; then he left her and went after the deer.","page":1389,"meaning_status":"draft"}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":1391,"lines":[{"gurmukhi":"ਸੀੜਿਨ ਬੀਚ ਨ੍ਰਿਪਤਿ ਲਗ ਰਹਿਯੋ। ਤੀਰ ਕਮਾਨ ਹਾਥ ਮੈ ਗਹਿਯੋ।","roman":"Seerin beech nripti lag rahiyo | teer kamaan haath mai gahiyo |","meaning_en":"The king stayed waiting on the stairs, holding bow and arrow in his hand.","page":1391,"meaning_status":"draft"},{"gurmukhi":"ਜਬ ਹੋਡੀ ਤਿਹ ਠਾ ਚਲਿ ਆਯੋ। ਬਿਹਸਿ ਰਿਸਾਲੁ ਬਚਨ ਸੁਨਾਯੋ। ੬੪।","roman":"Jab hodee tih thaa chali aayo | bihsi risaalu bachan sunaayo | 64 |","meaning_en":"When Hodi came to that place, Risalu laughed and spoke these words:","page":1391,"meaning_status":"draft"}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":1391,"lines":[{"gurmukhi":"ਅਬ ਤੁਮ ਕਹਿਯੋ ਪੌਰਖਹਿ ਧਰੋ। ਮੋ ਪਰ ਪ੍ਰਥਮ ਘਾਇ ਕਹ ਕਰੋ।","roman":"Ab tum kahiyo paurakhhi dharo | mo par pratham ghaai kah karo |","meaning_en":"\"Now,\" he said, \"show your manhood; strike the first blow at me.\"","page":1391,"meaning_status":"draft","note":"ਕਹਿਯੋ: 'said'; taken as marking Risalu's speech."},{"gurmukhi":"ਕੰਪਤ ਤ੍ਰਸਤ ਨਹਿ ਸਸਤ੍ਰ ਸੰਭਾਰਿਯੋ। ਤਨਿ ਧਨੁ ਬਾਨ ਰਿਸਾਲੂ ਮਾਰਿਯੋ। ੬੫।","roman":"Kanpat trasat nahi sasatr sanbhaariyo | tani dhanu baan risaaloo maariyo | 65 |","meaning_en":"Trembling and afraid, he did not take up his weapon; Risalu drew his bow and shot an arrow.","page":1391,"meaning_status":"draft"}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":1391,"lines":[{"gurmukhi":"ਲਾਗਤ ਬਾਨ ਧਰਨਿ ਗਿਰ ਪਰਿਯੋ। ਏਕੈ ਬ੍ਰਿਣ ਲਾਗਤ ਹੀ ਮਰਿਯੋ।","roman":"Laagat baan dharni gir pariyo | ekai brin laagat hee mariyo |","meaning_en":"As the arrow struck he fell to the ground; he died at that single wound.","page":1391,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੋ ਤੁਰਤ ਮਾਸੁ ਕਟਿ ਲੀਨੋ। ਭੂੰਜਿ ਕੋਕਿਲਾ ਕੌ ਲੈ ਦੀਨੋ। ੬੬।","roman":"Taa ko turat maasu kati leeno | bhoonji kokilaa kau lai deeno | 66 |","meaning_en":"At once he cut off his flesh, roasted it, and gave it to Kokila.","page":1391,"meaning_status":"draft"}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":1391,"lines":[{"gurmukhi":"ਜਬ ਤਿਹ ਮਾਸੁ ਕੋਕਿਲਾ ਖਾਯੋ। ਲਗਿਯੋ ਸਲੌਨੋ ਅਤਿ ਚਿਤ ਭਾਯੋ।","roman":"Jab tih maasu kokilaa khaayo | lagiyo salauno ati chit bhaayo |","meaning_en":"When Kokila ate that meat, it tasted savoury and greatly pleased her.","page":1391,"meaning_status":"draft"},{"gurmukhi":"ਜਾ ਕੇ ਤੁਲਿ ਮਾਸੁ ਕੋਊ ਨਾਹੀ। ਰਾਜਾ ਮੈ ਰੀਝੀ ਮਨ ਮਾਹੀ। ੬੭।","roman":"Jaa ke tuli maasu ko'oo naahee | raajaa mai reejhee man maahee | 67 |","meaning_en":"\"There is no meat to equal this; O king, I am delighted in my heart.\"","page":1391,"meaning_status":"draft"}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":1391,"lines":[{"gurmukhi":"ਤਬ ਰੀਸਾਲੂ ਬਚਨ ਉਚਾਰੇ। ਵਹੈ ਮਿਰਗ ਕਰ ਪਰਿਯੋ ਹਮਾਰੇ।","roman":"Tab reesaaloo bachan uchaare | vahai mirag kar pariyo hamaare |","meaning_en":"Then Risalu spoke these words: \"That same deer has fallen into my hands,","page":1391,"meaning_status":"draft"},{"gurmukhi":"ਜਿਯਤ ਤੂ ਜਾ ਸੌ ਭੋਗ ਕਮਾਯੋ। ਮਰੇ ਪ੍ਰਾਤ ਮਾਸੁ ਤਿਹ ਖਾਯੋ। ੬੮।","roman":"Jiyat too jaa sau bhog kamaayo | mare praat maasu tih khaayo | 68 |","meaning_en":"with whom you took your pleasure while he lived; now that he is dead you have eaten his flesh.\"","page":1391,"meaning_status":"draft","note":"ਮਰੇ ਪ੍ਰਾਤ: printed so; 'after his death' (or 'dead, this morning'); uncertain."}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":1391,"lines":[{"gurmukhi":"ਜਬ ਯਹ ਤਨਿਕ ਭਨਿਕ ਸੁਨਿ ਪਈ। ਲਾਲ ਹੁਤੀ ਪਿਯਰੀ ਹ੍ਵੈ ਗਈ।","roman":"Jab yah tanik bhanik suni paee | laal hutee piyree hvai gaee |","meaning_en":"When the least hint of this reached her ears, she who was rosy turned pale.","page":1391,"meaning_status":"draft"},{"gurmukhi":"ਧ੍ਰਿਗ ਜਿਯਬੋ ਇਹ ਜਗਤ ਹਮਾਰੋ। ਜਿਨ ਘਾਯੋ ਨਿਜੁ ਮੀਤ ਪ੍ਯਾਰੋ। ੬੯।","roman":"Dhrig jiybo ih jagat hamaaro | jin ghaayo niju meet pyaaro | 69 |","meaning_en":"\"Cursed is my living in this world, since my own dear friend has been killed.\"","page":1391,"meaning_status":"draft","note":"ਜਿਨ ਘਾਯੋ: 'who killed'; may mean 'I, who caused my dear friend's death' or a curse on him who killed; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1391,"meaning_status":"draft"},{"type":"verse","number":[70],"number_text":"੭੦।","page":1391,"lines":[{"gurmukhi":"ਸੁਨਤ ਕਟਾਰੀ ਨ੍ਰਿਪਤਿ ਕੀ ਲੈ ਅਪਨੇ ਉਰਿ ਮਾਰਿ।","roman":"Sunat kataaree nripti kee lai apne uri maari |","meaning_en":"On hearing it she took the king's dagger and struck it into her own breast;","page":1391,"meaning_status":"draft"},{"gurmukhi":"ਉਰਿ ਹਨਿ ਧੋਲਹਰ ਤੇ ਗਿਰੀ ਹੋਡਿਹਿ ਨੈਨ ਨਿਹਾਰ। ੭੦।","roman":"Uri hani dholhar te giree hodihi nain nihaar | 70 |","meaning_en":"having struck her breast she fell from the palace, having beheld Hodi with her eyes.","page":1391,"meaning_status":"draft"}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":1391,"lines":[{"gurmukhi":"ਉਦਰ ਕਟਾਰੀ ਮਾਰਿ ਕੈ ਪਰੀ ਮਹਲ ਤੈ ਟੂਟਿ।","roman":"Udar kataaree maari kai paree mahal tai tooti |","meaning_en":"Driving the dagger into her belly she fell headlong from the palace;","page":1391,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਘਰੀ ਸਸਤਕ ਰਹੀ ਬਹੁਰਿ ਪ੍ਰਾਨ ਗੇ ਛੂਟਿ। ੭੧।","roman":"Ek gharee sastak rahee bahuri praan ge chhooti | 71 |","meaning_en":"for one ghari she lay still breathing, then her life departed.","page":1391,"meaning_status":"draft","note":"ਸਸਤਕ: read as 'breathing, alive'; uncertain. A ghari is about 24 minutes."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1391,"meaning_status":"draft"},{"type":"verse","number":[72],"number_text":"੭੨।","page":1391,"lines":[{"gurmukhi":"ਗ੍ਰਿਹ ਤੇ ਟੂਟਿ ਧਰਨਿ ਪਰ ਪਰੀ। ਲਾਜ ਮਰਤ ਜਮਪੁਰ ਮਗੁ ਧਰੀ।","roman":"Grih te tooti dharni par paree | laaj marat jampur magu dharee |","meaning_en":"Falling from the house she dropped upon the ground; dying of shame she took the road to Yama's city.","page":1391,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਚਲ ਤਹਾ ਰਿਸਾਲੂ ਆਯੋ। ਮਾਸ ਕੂਕਰਨ ਦੁਹੂੰ ਖਵਾਯੋ। ੭੨।","roman":"Tab chal tahaa risaaloo aayo | maas kookran duhoon khavaayo | 72 |","meaning_en":"Then Risalu came there, and fed the flesh of both to the dogs.","page":1391,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1391,"meaning_status":"draft"},{"type":"verse","number":[73,1],"number_text":"੭੩। ੧।","page":1391,"lines":[{"gurmukhi":"ਜੋ ਬਨਿਤਾ ਪਤਿ ਆਪਨੋ ਤ੍ਯਾਗ ਔਰ ਪੈ ਜਾਇ।","roman":"Jo banitaa pati aapno tyaag aur pai jaai |","meaning_en":"The woman who forsakes her own husband and goes to another,","page":1391,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਐਸੋ ਪੁਨਿ ਤੁਰਤ ਹੀ ਕ੍ਯੋ ਨਹਿ ਲਹਤ ਸਜਾਇ। ੭੩। ੧।","roman":"So aiso puni turat hee kyo nahi lahat sajaai | 73 | 1 |","meaning_en":"why should she not at once receive such punishment?","page":1391,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਸਤਾਨਵੋ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade sataanvo charitr samaaptam","meaning_en":"Thus ends the ninety-seventh charitra of the Charitropakhyan, of the wiles of women, in the dialogue between the minister and the king,; complete.","page":1391,"meaning_status":"draft"},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੯੭। ੧੭੯੭। ਅਫਜੂੰ।","roman":"Satu subham satu | 97 | 1797 | aphjoon |","meaning_en":"True, auspicious, true. 97. 1797. It continues.","page":1391,"meaning_status":"draft","note":"ਅਫਜੂੰ: Persian afzun, 'increasing'."}],"page":1391,"number":[97,1797]}});
